await check("Blocked manual tasks and failed AI children have no acceptance bypass",async()=>{for(const row of [project({tasks:[task("facts",{status:"blocked"})]}),project({tasks:[task("draft",{kind:"workflow",status:"held",workflow_id:"fixture-workflow",child:{kind:"mission",id:"mission-fixture",status:"failed"},execution_preview:preview()})]})]){const h=harness({row});await h.open();assert(!h.find("Accept reviewed step"));assert(!h.find("Reject with note"));assert.equal(h.writes().length,0);}});
await check("Read-only mission receipt links use existing approval navigation",async()=>{const h=harness({row:project({tasks:[task("draft",{kind:"workflow",status:"active",workflow_id:"fixture-workflow",child:{kind:"mission",id:"mission-fixture",status:"waiting_approval",approval_count:1},execution_preview:preview()})]})});await h.open();await h.find("Inspect mission and approvals").fire("click");assert.deepEqual(h.missions,["mission-fixture"]);assert.equal(h.writes().length,0);});
await check("Only safe recorded artifact paths with valid hashes can open",async()=>{const h=harness({row:project({tasks:[task("facts",{status:"completed",evidence:{assurance:"checked_artifacts",artifacts:[{path:"reports/verified.txt",sha256:sha("a"),bytes:4},{path:"../escape.txt",sha256:sha("b"),bytes:4},{path:"reports/bad.txt",sha256:"bad",bytes:4}]}})]})});await h.open();assert(h.find("reports/verified.txt"));assert(!h.find("../escape.txt"));assert(!h.find("reports/bad.txt"));await h.find("reports/verified.txt").fire("click");assert.deepEqual(h.artifacts,["reports/verified.txt"]);assert.match(h.body.textContent,/checked child artifacts/);assert.equal(h.writes().length,0);});
await check("Untrusted objective task and prompt strings stay inert",async()=>{const p=project();p.objective="<script>doNotRun()</script>";p.tasks[1].execution_preview.workflow.prompt="<img src=x onerror=bad()>";const h=harness({row:p});await h.open();await h.review();assert.equal(h.all().filter(e=>["SCRIPT","IMG"].includes(e.tagName)).length,0);assert.match(h.body.textContent,/<script>doNotRun\(\)<\/script>/);assert.match(h.body.textContent,/<img src=x onerror=bad\(\)>/);});
await check("Global autonomy pause preserves reads and blocks mutations",async()=>{const h=harness({paused:true});await h.open();assert(h.find("Create project").disabled);assert(h.find("Review cycle").disabled);assert(h.find("Accept reviewed step").disabled);await h.find("Accept reviewed step").fire("click");await h.api.load();assert.equal(h.writes().length,0);assert.match(h.body.textContent,/Global autonomy is paused/);assert(h.aria("Open project Fictional local pilot"));});
await check("A failed read disables edits without silently replacing saved evidence",async()=>{const h=harness();await h.open();h.handler=(p,o)=>{if(p==="/workroom")throw Error("Synthetic read failed");return h.reply(p,o);};await h.api.load();assert(h.find("Edit project plan").disabled);assert(h.find("Accept reviewed step").disabled);assert.match(h.body.textContent,/Synthetic read failed/);assert.equal(h.writes().length,0);});
await check("Held cycles remain held and cannot be renewed through Review cycle",async()=>{const h=harness({row:project({cycle:cycle({status:"held",reason:"Actual child evidence was not verified."})})});await h.open();assert(h.find("Review cycle").disabled);assert(h.find("Stop after this step").disabled);assert.match(h.body.textContent,/Actual child evidence was not verified/);assert.equal(h.writes().length,0);});
await check("Stop binds the actual cycle and honestly allows an already linked child to finish",async()=>{const h=harness({row:project({cycle:cycle()})});await h.open();assert.match(h.body.textContent,/already linked queued or running child may still finish/);await h.find("Stop after this step").fire("click");await Promise.resolve();const write=h.writes()[0];assert.equal(write.path,"/workroom/cycles/stop");assert.equal(write.options.body.project_id,"fixture-project");assert.equal(write.options.body.cycle_id,"cycle-fixture");assert.equal(write.options.body.expected_revision,7);assert.equal(h.app.state.status.paused,false);});
await check("Explicit advancement is a bounded CAS request and never a read side effect",async()=>{const h=harness({row:project({cycle:cycle()})});await h.open();assert.equal(h.writes().length,0);await h.find("Inspect / advance cycle").fire("click");const write=h.writes()[0];assert.equal(write.path,"/workroom/reconcile");assert.equal(write.options.body.cycle_id,"cycle-fixture");assert.equal(write.options.body.expected_revision,7);});
await check("Lost POST responses stay uncertain and are never automatically replayed",async()=>{const h=harness();await h.open();await set(h.body,"review_note","Reviewed fictional facts.");h.handler=(p,o)=>{if(o)throw Error("Synthetic lost response");return h.reply(p,o);};await h.find("Accept reviewed step").fire("click");assert.equal(h.writes().length,1);assert.match(h.body.textContent,/no retry was made/);assert(h.find("Create project").disabled);h.handler=null;await h.api.load();assert.equal(h.writes().length,1);assert(h.find("Create project").disabled);});
await check("Definite validation and CAS rejection require fresh reads rather than an absent receipt",async()=>{for(const status of [400,409]){const h=harness();await h.open();await set(h.body,"review_note","Reviewed fictional facts.");h.handler=(p,o)=>{if(o)throw Object.assign(Error("Synthetic rejected request"),{status});return h.reply(p,o);};const count=h.calls.length;await h.find("Accept reviewed step").fire("click");assert.equal(h.calls.length,count+1);assert.equal(h.writes().length,1);assert(h.find("Create project").disabled);assert(!h.find("Inspect request receipt"));assert.match(h.body.textContent,/Refresh projects before preparing another action/);h.handler=null;await h.api.load();assert.equal(h.find("Create project").disabled,false);assert.equal(h.writes().length,1);}});
await check("Server or unknown failures keep exact receipt uncertainty even when a response exists",async()=>{const h=harness();await h.open();await set(h.body,"review_note","Reviewed fictional facts.");h.handler=(p,o)=>{if(o)throw Object.assign(Error("Synthetic server failure"),{status:500});return h.reply(p,o);};await h.find("Accept reviewed step").fire("click");assert(h.find("Inspect request receipt"));assert(h.find("Create project").disabled);assert.equal(h.writes().length,1);});
await check("Uncertainty needs receipt inspection plus a separate owner acknowledgement",async()=>{const h=harness();await h.open();await set(h.body,"review_note","Reviewed facts.");h.handler=(p,o)=>{if(o)throw Error("Synthetic lost response");return h.reply(p,o);};await h.find("Accept reviewed step").fire("click");h.handler=null;assert(input(h.body,"receipt_inspected").disabled);assert(h.find("Acknowledge this tab's uncertainty").disabled);await h.find("Inspect request receipt").fire("click");assert.equal(h.find("Acknowledge this tab's uncertainty").disabled,true);await set(h.body,"receipt_inspected",true,"change");await h.find("Acknowledge this tab's uncertainty").fire("click");assert.match(h.body.textContent,/Saved server holds still apply/);assert.equal(h.writes().length,1);assert.equal(h.find("Create project").disabled,false);});
await check("Failed request inspection retains uncertainty and sends no additional writes",async()=>{const h=harness();await h.open();await set(h.body,"review_note","Reviewed facts.");h.handler=(p,o)=>{if(o||p.includes("/receipts/"))throw Error("Synthetic missing receipt");return h.reply(p,o);};await h.find("Accept reviewed step").fire("click");await h.find("Inspect request receipt").fire("click");assert.match(h.body.textContent,/The hold remains/);assert(h.find("Acknowledge this tab's uncertainty").disabled);assert.equal(h.writes().length,1);});
await check("Concurrent gestures create one child authorization request",async()=>{const h=harness();await h.open();await h.review();await h.confirm();const wait=deferred();h.handler=(p,o)=>o?wait.promise:h.reply(p,o);const button=h.find("Start reviewed cycle"),first=button.fire("click");await button.fire("click");assert.equal(h.writes().length,1);h.api.leave();wait.resolve({revision:8,project_id:"fixture-project"});await first;assert.equal(h.toasts.length,0);});
await check("Lock clears source evidence drafts and ignores a late project read",async()=>{const h=harness();await h.api.load();const wait=deferred();h.handler=(p,o)=>p.startsWith("/workroom/projects/")?wait.promise:h.reply(p,o);const pending=h.aria("Open project Fictional local pilot").fire("click");h.app.state.authenticated=false;h.api.locked();wait.resolve({schema:1,revision:7,project:project()});await pending;assert(!h.body.textContent.includes("Fictional local pilot"));assert(!h.body.textContent.includes(sha("d")));assert.equal(h.writes().length,0);});
await check("An in-flight write after lock never restores private data and remains uncertain on re-pairing",async()=>{const h=harness();await h.open();await set(h.body,"review_note","Private fictional review note.");const wait=deferred();h.handler=(p,o)=>o?wait.promise:h.reply(p,o);const pending=h.find("Accept reviewed step").fire("click");h.app.state.authenticated=false;h.api.locked();wait.resolve({revision:8,project_id:"fixture-project"});await pending;assert(!h.body.textContent.includes("Private fictional"));assert.equal(h.toasts.length,0);h.app.state.authenticated=true;h.app.state.token="new-synthetic-owner";h.handler=null;await h.api.load();assert(h.find("Create project").disabled);assert(h.find("Inspect request receipt"));assert.equal(h.writes().length,1);});
await check("Leaving after inspected uncertainty discards private receipt contents and confirmation",async()=>{const h=harness();await h.open();await set(h.body,"review_note","Reviewed facts.");h.handler=(p,o)=>{if(o)throw Error("Synthetic lost response");return h.reply(p,o);};await h.find("Accept reviewed step").fire("click");h.handler=null;await h.find("Inspect request receipt").fire("click");await set(h.body,"receipt_inspected",true,"change");h.api.leave();assert.equal(h.body.textContent,"");await h.api.load();assert(input(h.body,"receipt_inspected").disabled);assert.equal(input(h.body,"receipt_inspected").checked,false);assert(!h.body.textContent.includes('"project_id"'));});
await check("Late write completion after view departure does not leave future sessions permanently busy",async()=>{const h=harness();await h.open();await set(h.body,"review_note","Reviewed facts.");const wait=deferred();h.handler=(p,o)=>o?wait.promise:h.reply(p,o);const pending=h.find("Accept reviewed step").fire("click");h.api.leave();wait.resolve({revision:8,project_id:"fixture-project"});await pending;h.handler=null;await h.api.load();assert.equal(h.find("Refresh projects").disabled,false);assert(h.find("Inspect request receipt"));assert.equal(h.toasts.length,0);});
await check("No background timer polling external resources executable markup or model endpoint exists",async()=>{assert.doesNotMatch(source,/setInterval\(|setTimeout\(|fetch\(|innerHTML|eval\(/);assert.doesNotMatch(source,/\/api\/chat|\/chat\b|https?:\/\//);const css=fs.readFileSync(path.join(root,"ariadne/static/workroom.css"),"utf8");assert.doesNotMatch(css,/@import|url\(/);assert.match(css,/max-width:440px/);assert.match(css,/:focus-visible/);});
